import{_ as e,o as i,c as r,a2 as t}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Управление набором модов","description":"","frontmatter":{"pageId":"admins/modpacks","contentRevision":2},"headers":[],"relativePath":"ru/admins/modpacks.md","filePath":"ru/admins/modpacks.md"}'),l={name:"ru/admins/modpacks.md"};function o(s,a,d,n,c,p){return i(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="управление-набором-модов" tabindex="-1">Управление набором модов <a class="header-anchor" href="#управление-набором-модов" aria-label="Permalink to &quot;Управление набором модов&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><ol><li>Подготовь проверенный набор в отдельной установке игры. Зафиксируй ModsConfig.xml, порядок, версии и hash.</li><li>Выполни modpack import --from &lt;ModsConfig.xml&gt; --mods-dir &lt;folders&gt; --dry-run. После проверки добавь --server/--token для отправки требований.</li><li>modpack defs собирает разрешённые ThingDef/PawnKindDef; пустой список выключает эту проверку. Общие настройки импортируются только для выбранных --mod, загружаемых ниже Rimlink.</li><li>Для серверной доставки выполни modpack package requirements --output &lt;new-file&gt;, затем package pack --source &lt;redistributable-folders&gt; --requirements &lt;file&gt; --output &lt;new-directory&gt;.</li><li>Проверь archive.zip и manifest.json, лицензии и настройки. package publish --from &lt;directory&gt; требует --confirm-redistribution; --confirm-public и --confirm-shared-settings подтверждают соответствующее раскрытие. Проверь package status; unpublish снимает публикацию.</li></ol><p>Протестируй чистого клиента после изменения коллекции.</p><h2 id="modpack-release" tabindex="-1">Версия коллекции как отдельный релиз <a class="header-anchor" href="#modpack-release" aria-label="Permalink to &quot;Версия коллекции как отдельный релиз {#modpack-release}&quot;">​</a></h2><p>Сначала проверь набор на отдельном клиенте. Import --dry-run показывает будущие требования; фактическую отправку выполняй после ревью. Укажи каталоги Steam/local/Workshop, чтобы версии и хеши соответствовали реально загруженным файлам. Общие настройки импортируй только выбранным модам; они могут содержать персональные пути и секреты.</p><p>Requirements и ZIP доставки — разные сущности. После изменения требований старый ZIP может стать несовместимым. Пересобери из разрешённых к распространению исходных папок, проверь manifest/archive и отдельное согласие на настройки. Core/DLC и сама игра не входят в пакет.</p><h2 id="delivery-accept" tabindex="-1">Приёмка новой сборки и откат публикации <a class="header-anchor" href="#delivery-accept" aria-label="Permalink to &quot;Приёмка новой сборки и откат публикации {#delivery-accept}&quot;">​</a></h2><p>На чистом тестовом клиенте проверь полный цикл: diff → скачивание → проверка → согласие → restart → повторный вход. Отдельно проверь существующую конфликтную unmanaged-копию и отказ без перезаписи. Это не разрешение удалять пользовательскую папку Mods.</p><p>При ошибке unpublish снимает доступность пакета, но не возвращает автоматически уже установленные клиенты и не отменяет импортированные требования. Сохрани предыдущие requirements, исходный пакет и настройки для согласованного возврата. Полный DataDir backup не заменяет отдельную сохранность исходных модов/лицензий и внешнего каталога доставки.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Не упаковывай каталог игры, Core/DLC и секреты модов. Pack требует полный подготовленный набор и новый output. Публикация — отдельное внешнее действие оператора. Изменение требований может сделать прежний опубликованный пакет неактуальным.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./cli">Справочник CLI</a></li><li><a href="./../players/modpacks">Набор модов сервера</a></li><li><a href="./updating">Обновление сервера и клиентов</a></li></ul>',15)])])}const h=e(l,[["render",o]]);export{u as __pageData,h as default};
